parameters.new_string:
  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts a list_sessions frame with optional limit and before cursor while stripping unknown fields', () => {
    expect({
      bare: validateMessage({type: 'list_sessions'}),
      isoWithExtras: validateMessage({
        type: 'list_sessions',
        limit: 0,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1', extra: 1},
        userId: 'u2',
      }),
      epochCursor: validateMessage({
        type: 'list_sessions',
        limit: 10,
        before: {updatedAt: 1735689600000, sessionId: 's2'},
      }),
    }).toEqual({
      bare: {valid: true, data: {type: 'list_sessions'}},
      isoWithExtras: {
        valid: true,
        data: {type: 'list_sessions', limit: 0, before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'}},
      },
      epochCursor: {
        valid: true,
        data: {type: 'list_sessions', limit: 10, before: {updatedAt: 1735689600000, sessionId: 's2'}},
      },
    });
  });

  it('rejects a list_sessions frame with a malformed limit or before cursor', () => {
    const invalidPayloads = [
      {type: 'list_sessions', limit: 'ten'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', limit: null},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: null},
      {type: 'list_sessions', before: []},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: Number.NaN, sessionId: 's1'}},
    ];

    expect(invalidPayloads.map(payload => validateMessage(payload).valid)).toEqual(
      Array(invalidPayloads.length).fill(false)
    );
  });
});
